$base=rtrim((string)config('app.base_path'),'/');$orders=$orders??[];$order=$order??null;function foEsc(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}function foMoney(mixed $v):string{return '₹'.number_format((float)$v,2);}function foLabel(string $s):string{return ucwords(strtolower(str_replace('_',' ',$s)));}
