<style>.fo-page{max-width:560px;margin:auto;padding:13px 13px 94px;color:#14251f}.fo-head{display:flex;gap:9px;align-items:center}.fo-head a{font-size:27px;text-decoration:none;color:#173c32}.fo-head h1{margin:0;font-size:20px}.fo-head p{margin:2px 0;color:#74827d;font-size:10px}.fo-card{display:block;text-decoration:none;color:inherit;background:#fff;border:1px solid #e0ebe6;border-radius:14px;padding:11px;margin:8px 0}.fo-top{display:flex;justify-content:space-between;gap:8px}.fo-name{font-size:13px;font-weight:900}.fo-status{font-size:9px;color:#087d64;font-weight:900}.fo-meta{font-size:9px;color:#708079;margin-top:4px}.fo-total{font-size:14px;font-weight:950;margin-top:7px}.fo-hero{background:#eaf7f2;border-radius:14px;padding:12px;margin:10px 0}.fo-hero strong{display:block;font-size:15px;color:#087d64}.fo-hero span{display:block;font-size:9px;color:#5d7268;margin-top:4px}.fo-section{background:#fff;border:1px solid #e1ebe6;border-radius:14px;padding:11px;margin:8px 0}.fo-section h2{font-size:12px;margin:0 0 8px}.fo-line{display:flex;justify-content:space-between;gap:8px;padding:6px 0;border-bottom:1px solid #edf2f0;font-size:10px}.fo-history{border-left:2px solid #bfe1d5;padding-left:10px}.fo-event{margin:9px 0}.fo-event b{font-size:10px}.fo-event small{display:block;color:#7a8983;font-size:8px;margin-top:2px}.fo-event p{font-size:9px;color:#62746c;margin:3px 0}.fo-nav{position:fixed;left:50%;bottom:6px;transform:translateX(-50%);width:min(540px,calc(100% - 14px));background:#fff;border:1px solid #e1ebe7;box-shadow:0 7px 22px rgba(0,0,0,.1);border-radius:18px;display:grid;grid-template-columns:repeat(4,1fr);padding:4px;z-index:30}.fo-nav a{text-decoration:none;color:#73827c;text-align:center;padding:5px 3px;font-size:9px;font-weight:700}.fo-nav a.active{color:#087d64}.fo-nav i{display:block;font-style:normal;font-size:17px}</style>
<div class="fo-page"><?php if(!$order): ?><header class="fo-head"><a href="<?=foEsc($base)?>/member/fresh-food">‹</a><div><h1>Fresh Food Orders</h1><p>Your Fresh Food orders</p></div></header><?php foreach($orders as $o): $st=strtoupper((string)$o['status']); ?><a class="fo-card" href="<?=foEsc($base)?>/member/fresh-food/orders/<?=foEsc($o['id'])?>"><div class="fo-top"><span class="fo-name">🥬 <?=foEsc($o['fresh_food_name']??'Fresh Food')?></span><span class="fo-status"><?=foEsc(foLabel($st))?></span></div><div class="fo-meta"><?=foEsc($o['order_no'])?> · <?=foEsc($o['order_type'])?></div><div class="fo-meta"><?=foEsc($o['created_at'])?></div><div class="fo-total"><?=foMoney($o['total'])?></div></a><?php endforeach; if(!$orders): ?><div class="fo-card" style="text-align:center;color:#687a72">No Fresh Food orders yet.</div><?php endif; ?><?php else: $status=strtoupper((string)$order['status']);$message=['PENDING'=>'Your order has been received and is waiting for store confirmation.','ACCEPTED'=>'The store accepted your order.','PACKING'=>'Your fresh food is being packed.','READY'=>'Your order is ready.','ASSIGNED'=>'A delivery person has been assigned.','OUT_FOR_DELIVERY'=>'Your fresh food is on the way.','DELIVERED'=>'Your order has been delivered.','COMPLETED'=>'Fresh Food order completed.','CANCELLED'=>'This order was cancelled.','REJECTED'=>'The store rejected this order.'][$status]??'Your order status has been updated.'; ?><header class="fo-head"><a href="<?=foEsc($base)?>/member/fresh-food/orders">‹</a><div><h1>Order <?=foEsc($order['order_no'])?></h1><p><?=foEsc($order['fresh_food_name'])?></p></div></header><div class="fo-hero"><strong><?=foEsc(foLabel($status))?></strong><span><?=foEsc($message)?></span></div><section class="fo-section"><h2>Items</h2><?php foreach(($order['items']??[]) as $i): ?><div class="fo-line"><span><?=foEsc($i['product_name'])?> · <?=foEsc($i['quantity'])?> <?=foEsc($i['unit'])?></span><b><?=foMoney($i['line_total'])?></b></div><?php endforeach; ?></section><section class="fo-section"><h2>Order summary</h2><div class="fo-line"><span>Gross subtotal</span><b><?=foMoney($order['gross_subtotal'])?></b></div><?php if((float)$order['item_discount']>0): ?><div class="fo-line"><span>Product discounts</span><b>−<?=foMoney($order['item_discount'])?></b></div><?php endif; ?><?php if((float)$order['coupon_discount']>0): ?><div class="fo-line"><span>Coupon (<?=foEsc($order['coupon_code'])?>)</span><b>−<?=foMoney($order['coupon_discount'])?></b></div><?php endif; ?><div class="fo-line"><span>Delivery</span><b id="ffDeliveryFee"><?=foMoney($order['delivery_fee']??0)?></b></div><div class="fo-line"><span>Total</span><b id="ffOrderTotal"><?=foMoney($order['total']??0)?></b></div></section><section class="fo-section"><h2>Status timeline</h2><div class="fo-history"><?php foreach(($order['status_history']??[]) as $h): ?><div class="fo-event"><b><?=foEsc(foLabel((string)$h['to_status']))?></b><small><?=foEsc($h['created_at'])?></small><?php if(!empty($h['note'])): ?><p><?=foEsc($h['note'])?></p><?php endif; ?></div><?php endforeach; ?></div></section><section class="fo-section"><h2>Delivery</h2><div class="fo-meta"><?=foEsc($order['delivery_address']??'Pickup order')?></div><div class="fo-meta" id="ffRouteDistance"><?php if(!empty($order['distance_km'])): ?>Road distance <?=foEsc(number_format((float)$order['distance_km'],2))?> km<?php elseif(($order['order_type']??'')==='DELIVERY'): ?>Road distance is being calculated…<?php endif; ?></div><div class="fo-meta" id="ffRouteEta"><?php if(!empty($order['eta_minutes'])): ?>Estimated delivery time <?=foEsc((int)$order['eta_minutes'])?> min<?php elseif(($order['order_type']??'')==='DELIVERY'): ?>Estimated delivery time is being calculated…<?php endif; ?></div><div class="fo-meta" id="ffRouteStatus"><?php if(($order['order_type']??'')==='DELIVERY' && ($order['route_status']??'PENDING')!=='COMPLETED'): ?>Calculating road route securely…<?php endif; ?></div></section><?php endif; ?><?php include __DIR__.'/../Shared/fresh-food-cart-widget.php'; ?><?php include __DIR__.'/../Shared/member-notification-widget.php'; ?></div><nav class="fo-nav"><a href="<?=foEsc($base)?>/member"><i>⌂</i>Home</a><a class="active" href="<?=foEsc($base)?>/member/fresh-food"><i>🥬</i>Fresh</a><a href="<?=foEsc($base)?>/member/bookings"><i>▣</i>Bookings</a><a href="<?=foEsc($base)?>/member/profile"><i>♙</i>Profile</a></nav><?php if($order): ?><script>(()=>{const id=<?=json_encode((int)$order['id'])?>,base=<?=json_encode($base)?>,token=<?=json_encode($csrf??'')?>,initialRoute=<?=json_encode((string)($order['route_status']??'PENDING'))?>,type=<?=json_encode((string)($order['order_type']??''))?>;let routeStarted=false,poll=null;const money=v=>'₹'+Number(v||0).toFixed(2);function apply(d){if(!d)return;const rs=String(d.route_status||'');const dist=document.getElementById('ffRouteDistance'),eta=document.getElementById('ffRouteEta'),note=document.getElementById('ffRouteStatus'),fee=document.getElementById('ffDeliveryFee'),total=document.getElementById('ffOrderTotal');if(dist&&d.distance_km!==null&&d.distance_km!=='')dist.textContent='Road distance '+Number(d.distance_km).toFixed(2)+' km';if(eta&&d.eta_minutes!==null&&d.eta_minutes!=='')eta.textContent='Estimated delivery time '+parseInt(d.eta_minutes,10)+' min';if(fee&&d.delivery_fee!==null&&d.delivery_fee!=='')fee.textContent=money(d.delivery_fee);if(total&&d.total!==null&&d.total!=='')total.textContent=money(d.total);if(note){if(rs==='PROCESSING'||rs==='PENDING')note.textContent='Calculating road route securely…';else if(rs==='FAILED')note.textContent=(d.route_error||'Route calculation could not be completed.')+' Initial delivery fee retained.';else note.textContent='Road distance, ETA and final delivery fee calculated.';}}async function status(){try{const r=await fetch(base+'/member/fresh-food/orders/'+id+'/status',{headers:{Accept:'application/json'},cache:'no-store'});if(!r.ok)return null;const j=await r.json();if(j.success&&j.data){apply(j.data);return j.data;}}catch(e){}return null}async function process(){if(routeStarted||type!=='DELIVERY')return;routeStarted=true;const current=await status();if(current&&current.route_status==='COMPLETED')return;if(current&&current.route_status==='PROCESSING'){return;}try{const r=await fetch(base+'/member/fresh-food/orders/'+id+'/process-route',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded',Accept:'application/json'},body:new URLSearchParams({_token:token}),cache:'no-store'});const j=await r.json();if(j.success&&j.data){apply(j.data.order);if(j.data.status==='PROCESSING')return;}else{apply({route_status:'FAILED',route_error:j.message||'Route calculation could not be completed.'});}}catch(e){apply({route_status:'FAILED',route_error:'Route calculation is temporarily unavailable. Your order is still received.'});}}async function pollStatus(){const d=await status();if(!d)return;if(d.route_status==='COMPLETED'||d.route_status==='FAILED'){if(poll){clearInterval(poll);poll=null;}}}if(type==='DELIVERY'&&initialRoute!=='COMPLETED'){process();poll=setInterval(pollStatus,4000);}else if(type==='DELIVERY'){poll=setInterval(pollStatus,10000);}setTimeout(()=>{if(poll){clearInterval(poll);poll=null;}},120000);})();</script><?php endif; ?>
